import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import admin from '../services/admin';

export default function AdminLogin() {
  const [user, setUser] = useState('admin');
  const [pass, setPass] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    let mounted = true;
    // if already authenticated (csrf available), redirect to admin bookings
    admin.getCsrf().then(csrf => {
      if (!mounted) return;
      if (csrf) navigate('/admin/bookings');
    }).catch(() => {});
    return () => { mounted = false; };
  }, [navigate]);

  async function doLogin(e) {
    e && e.preventDefault && e.preventDefault();
    setError(null);
    setLoading(true);
    try {
      const res = await admin.login(user, pass);
      if (res.success) {
        navigate('/admin/bookings');
        return;
      }
      setError(res.error || 'Login failed');
    } catch (err) {
      setError(err && err.message ? err.message : 'Network error');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="w-full max-w-md bg-white p-6 rounded-lg shadow">
        <h2 className="text-xl font-semibold mb-4">Admin Login</h2>
        {error && <div className="mb-3 text-sm text-red-600">{error}</div>}
        <form onSubmit={doLogin}>
          <label className="block text-sm text-gray-600">User</label>
          <input className="w-full border rounded px-3 py-2 mb-3" value={user} onChange={e => setUser(e.target.value)} />
          <label className="block text-sm text-gray-600">Password</label>
          <input type="password" className="w-full border rounded px-3 py-2 mb-4" value={pass} onChange={e => setPass(e.target.value)} />
          <div className="flex items-center justify-between">
            <button type="submit" disabled={loading} className={`px-4 py-2 rounded bg-blue-600 text-white ${loading ? 'opacity-60' : 'hover:shadow'}`}>
              {loading ? 'Signing in...' : 'Sign in'}
            </button>
            <a className="text-sm text-gray-600" href="/">Back to site</a>
          </div>
        </form>
      </div>
    </div>
  );
}
